css:
.bm1 { display: flex; align-items: center; gap: 14px; text-decoration: none; }
.bm1__tile { display: grid; place-items: center; width: 46px; height: 46px; border-radius: 12px; background: var(--color-accent-ink); color: var(--color-accent); font-family: 'Playfair Display', Georgia, serif; font-weight: 700; font-size: 25px; letter-spacing: -2px; padding-right: 2px; }
.bm1__rule { width: 1px; height: 40px; background: var(--color-accent); }
.bm1__name { display: block; font-family: 'Playfair Display', Georgia, serif; font-weight: 600; font-size: 20px; letter-spacing: 3px; text-transform: uppercase; color: var(--color-text); line-height: 1; }
.bm1__sub { display: block; font-family: var(--font-text); font-weight: 600; font-size: 8.5px; letter-spacing: 2.5px; text-transform: uppercase; color: var(--color-text-muted); margin-top: 5px; }
@media (max-width: 900px) { .bm1__words { display: none; } }

.bm2 { display: inline-flex; flex-direction: column; gap: 5px; text-decoration: none; }
.bm2__name { font-family: 'Playfair Display', Georgia, serif; font-weight: 600; font-size: 22px; letter-spacing: 5px; text-transform: uppercase; color: var(--color-text); line-height: 1; padding-bottom: 6px; border-bottom: 1px solid var(--color-accent); }
.bm2__sub { font-family: var(--font-text); font-weight: 600; font-size: 8.5px; letter-spacing: 4px; text-transform: uppercase; color: var(--color-text-muted); }
@media (max-width: 520px) { .bm2__name { font-size: 17px; letter-spacing: 3px; } }

.bm3 { display: flex; align-items: center; gap: 14px; text-decoration: none; }
.bm3__seal { display: grid; place-items: center; width: 48px; height: 48px; border-radius: 50%; border: 1.5px solid var(--color-accent-ink); box-shadow: inset 0 0 0 3px var(--color-bg), inset 0 0 0 4px var(--color-accent); color: var(--color-accent-ink); font-family: 'Playfair Display', Georgia, serif; font-weight: 700; font-size: 19px; letter-spacing: -1px; padding-right: 1px; }
.bm3__name { display: block; font-family: 'Playfair Display', Georgia, serif; font-weight: 600; font-size: 19px; letter-spacing: 3px; text-transform: uppercase; color: var(--color-text); line-height: 1; }
.bm3__sub { display: block; font-family: var(--font-text); font-weight: 600; font-size: 8.5px; letter-spacing: 2.5px; text-transform: uppercase; color: var(--color-text-muted); margin-top: 5px; }
@media (max-width: 900px) { .bm3__words { display: none; } }

.bm4 { display: flex; align-items: center; gap: 12px; text-decoration: none; }
.bm4__tile { display: grid; place-items: center; width: 44px; height: 44px; border-radius: 9px; background: var(--color-accent); color: var(--color-accent-ink); font-family: var(--font-heading); font-weight: 900; font-size: 18px; letter-spacing: -1px; }
.bm4__name { font-family: var(--font-heading); font-weight: 900; font-size: 17px; line-height: 0.98; letter-spacing: -0.02em; text-transform: uppercase; color: var(--color-text); }
@media (max-width: 900px) { .bm4__name { display: none; } }

.bm5 { display: flex; align-items: center; gap: 14px; text-decoration: none; }
.bm5__mono { display: inline-flex; align-items: baseline; font-family: 'Playfair Display', Georgia, serif; font-weight: 700; font-size: 38px; line-height: 1; color: var(--color-accent-ink); }
.bm5__mono span:nth-child(2) { margin-left: -11px; }
.bm5__rule { width: 1px; height: 38px; background: var(--color-accent); }
.bm5__name { display: block; font-family: 'Playfair Display', Georgia, serif; font-weight: 600; font-size: 18px; letter-spacing: 3px; text-transform: uppercase; color: var(--color-text); line-height: 1; }
.bm5__sub { display: block; font-family: var(--font-text); font-weight: 600; font-size: 8.5px; letter-spacing: 2.5px; text-transform: uppercase; color: var(--color-text-muted); margin-top: 5px; }
@media (max-width: 900px) { .bm5__words { display: none; } }
